<?php require_once __DIR__.'/../config/config.php'; require_admin(); $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$active=(int)$_POST['active'];$pdo->prepare('UPDATE products SET active=? WHERE id=?')->execute([$active,$id]);flash('ok','Produto atualizado.');redirect('products.php');} $rows=$pdo->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll(); require __DIR__.'/includes/header.php'; ?><div class="content"><div class="actions" style="justify-content:space-between"><div><h1>Produtos</h1><p class="muted">Cadastre preços, estoque, tamanhos, cores e fotos.</p></div><a class="btn" href="product_form.php">+ Novo produto</a></div><div class="panel" style="margin-top:20px"><table class="table"><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th></th></tr><?php foreach($rows as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category']??'—')?></td><td><?=money($p['price'])?></td><td><?=e($p['stock'])?></td><td><?=e($p['active']?'Ativo':'Inativo')?></td><td><a class="btn" href="product_form.php?id=<?=$p['id']?>">Editar</a></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/includes/footer.php';
